const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const g = $input.first().json.body || $input.first().json;
const jobId = String(g.jobId || '');
if (!UUID.test(jobId)) throw new Error('gecersiz jobId');
return [{ json: { jobId } }];

const y = $input.first().json || {};
const durum = y.statusCode || 0;
const govde = y.body || {};
const jobId = $('Girdiyi doğrula').first().json.jobId;
if (durum === 200) {
  return [{ json: { ok: true, jobId, sent: govde.sent, failed: govde.failed, dropped: govde.dropped, reason: govde.reason || null } }];
}
const kod = (govde.error && govde.error.code) || 'bilinmiyor';
if (durum === 404 && kod === 'no_job') {
  return [{ json: { ok: false, jobId, beklemede: true, kod } }];
}
throw new Error('bildirim gonderilemedi: ' + durum + ' ' + kod);
